<script setup>
import {ref,onMounted} from 'vue';import {useClinicContextStore} from '../../stores/clinicContext';import {useAppointmentStore} from '../../stores/appointments';import {appointmentService} from '../../services/appointments';import AppointmentScheduleView from './AppointmentScheduleView.vue';import FormErrors from '../ui/FormErrors.vue';
const props=defineProps({patientId:Number,doctorId:Number});const context=useClinicContextStore(),store=useAppointmentStore(),rows=ref([]),meta=ref(null),busy=ref(false),error=ref(null);
async function load(page=1){if(!context.allowed('appointments'))return;busy.value=true;error.value=null;try{const results=await Promise.allSettled([appointmentService.list({patient_id:props.patientId,doctor_id:props.doctorId,page}),appointmentService.options(context.data.branch.id)]);for(const r of results)if(r.status==='rejected')throw r.reason;rows.value=results[0].value.data.data;meta.value=results[0].value.data.meta;store.options=results[1].value.data.data;}catch(e){error.value=e;}finally{busy.value=false;}}onMounted(()=>load());
</script>
<template><section class="clinic-panel"><div class="clinic-card-heading"><h2>Appointments</h2><RouterLink v-if="context.allowed('appointments')&&context.can('appointments.create')" class="btn" :to="{path:'/app/appointments/create',query:{patient_id:patientId,doctor_id:doctorId}}">Book Appointment</RouterLink></div><p v-if="!context.allowed('appointments')" class="empty-state">Appointments are unavailable with your access.</p><template v-else><FormErrors :error="error"/><p v-if="busy" class="empty-state">Loading appointments…</p><button v-else-if="error" class="btn" @click="load()">Try again</button><AppointmentScheduleView v-else :rows="rows" :meta="meta" @page="load"/></template></section></template>
